Method.Implementation:
Set pStatus = $$$OK
Set tResult = {}
Try {
    Set tDash = ##class(%DeepSee.Dashboard.Utils).%OpenDashboard(pDashboardFullName, .pStatus)
    If $$$ISERR(pStatus) Quit
    If '$IsObject(tDash) {
        Set pStatus = $$$ERROR($$$GeneralError, "Dashboard not found: "_pDashboardFullName)
        Quit
    }

    Set tResult.title = tDash.title
    Set tResult.dashboardName = tDash.fullName

    Set tSheets = []
    Set tSkipped = []
    For i=1:1:tDash.widgets.Count() {
        Set tWidget = tDash.widgets.GetAt(i)
        If '..%IsPivotWidgetType(tWidget.type) {
            Do tSkipped.%Push({"widgetName": (tWidget.name), "title": (tWidget.title), "type": (tWidget.type)})
            Continue
        }
        Do tSheets.%Push(..%BuildWidgetSheet(tWidget))
    }
    Set tResult.sheets = tSheets
    Set tResult.skipped = tSkipped
}
Catch ex {
    Set pStatus = ex.AsStatus()
}
Quit tResult

Set tSheet = {}
Set tSheet.widgetName = pWidget.name
Set tSheet.title = $Select(pWidget.title'="":pWidget.title, 1:pWidget.name)
Try {
    Set tPivotName = pWidget.dataSource
    Set tExt = $Piece(tPivotName,".",$Length(tPivotName,"."))
    If (tPivotName = "") || (tExt '= "pivot") {
        // KPI ("*.kpi"), metric, worksheet, or no data source at all (e.g. a chart
        // pulling from another widget) - %IsPivotWidgetType() only looks at the
        // widget's rendering CLASS, not what it's actually pointed at, so this can
        // still happen for a widget using BIExport.UI.Widget.pivot (or stock "pivot")
        // whose dataSource isn't a plain saved pivot. Same non-fatal "error" field
        // treatment as any other per-widget failure - just a more specific message.
        Set tSheet.error = "Widget's data source is not a saved pivot (dataSource="""_tPivotName_"""); skipping its data."
        Quit
    }
    If '##class(%DeepSee.UserLibrary.Utils).%FolderItemExists(tPivotName) {
        Set tSheet.error = "Saved pivot not found: "_tPivotName
        Quit
    }

    Set tPivot = ##class(%DeepSee.UserLibrary.Utils).%OpenFolderItem(tPivotName,.tSC)
    If $$$ISERR(tSC) Throw ##class(%Exception.StatusException).CreateFromStatus(tSC)

    Set tTable = ##class(%DeepSee.Component.pivotTable).%New()
    Set tSC = tPivot.%CopyToComponent(tTable)
    If $$$ISERR(tSC) Throw ##class(%Exception.StatusException).CreateFromStatus(tSC)

    Set tMDX = tTable.GetCurrentQueryText("export")
    // GetCurrentQueryText() never throws - on failure it returns the error text
    // itself as the "MDX" (see its own compiled source), so a failure has to be
    // caught by inspecting the string rather than a status/exception.
    If ($Extract(tMDX,1,6) = "ERROR:") {
        Set tSheet.error = tMDX
        Quit
    }

    Set tOptions = {}
    Set tOptions.title = tSheet.title
    Set tOptions.subtitle = tTable.printSubtitle
    Set tOptions.cube = tTable.cubeName
    Set tOptions.listing = tTable.listing
    // Crossed rowTotals/columnTotals(+Agg) mapping - see CLAUDE.md gotcha #8 and
    // BIExport.UI.Widget.pivot's buildExportURL() doc comment: table.rowTotals
    // renders a Totals ROW in the widget (-> our COLUMNTOTALS), table.columnTotals
    // renders a Totals COLUMN (-> our ROWTOTALS). Same crossing, just read straight
    // off the saved pivot's own properties instead of a live client-side table.
    Set tOptions.rowTotals = tTable.columnTotals
    Set tOptions.columnTotals = tTable.rowTotals
    Set tOptions.rowTotalAgg = $Select(tTable.columnTotalAgg'="":tTable.columnTotalAgg, 1:"sum")
    Set tOptions.columnTotalAgg = $Select(tTable.rowTotalAgg'="":tTable.rowTotalAgg, 1:"sum")

    Set tSheet.data = ##class(BIExport.MDXExport).BuildExportData(tMDX, tOptions)
}
Catch ex {
    Set tSheet.error = ex.DisplayString()
}
Quit tSheet

Set tSC = $$$OK
Try {
    Set tDash = ##class(%DeepSee.Dashboard.Utils).%OpenDashboard(pDashboardFullName, .tSC)
    If $$$ISERR(tSC) Quit
    If '$IsObject(tDash) {
        Set tSC = $$$ERROR($$$GeneralError, "Dashboard not found: "_pDashboardFullName)
        Quit
    }

    Set tWidget = ""
    For i=1:1:tDash.widgets.Count() {
        Set w = tDash.widgets.GetAt(i)
        If (w.name = pWidgetName) {
            Set tWidget = w
            Quit
        }
    }
    If '$IsObject(tWidget) {
        Set tSC = $$$ERROR($$$GeneralError, "Widget not found on '"_pDashboardFullName_"': "_pWidgetName)
        Quit
    }

    If '..%IsPivotFamily(tWidget.type, pNewType) {
        Set tSC = $$$ERROR($$$GeneralError, "Widget '"_pWidgetName_"' has type '"_tWidget.type_"', not a recognized pivot-widget type - refusing to convert")
        Quit
    }

    Set tWidget.type = pNewType
    Set tSC = tDash.%Save()
    If $$$ISERR(tSC) Quit

    Write "Converted '"_pWidgetName_"' on '"_pDashboardFullName_"' to "_pNewType, !
}
Catch ex {
    Set tSC = ex.AsStatus()
}
Quit tSC

Set tSC = $$$OK
Try {
    Set tDash = ##class(%DeepSee.Dashboard.Utils).%OpenDashboard(pDashboardFullName, .tSC)
    If $$$ISERR(tSC) Quit
    If '$IsObject(tDash) {
        Set tSC = $$$ERROR($$$GeneralError, "Dashboard not found: "_pDashboardFullName)
        Quit
    }

    Set tConverted = 0
    For i=1:1:tDash.widgets.Count() {
        Set w = tDash.widgets.GetAt(i)
        If ..%IsPivotFamily(w.type, pNewType) {
            Set w.type = pNewType
            Set tConverted = tConverted + 1
        }
    }

    If (tConverted = 0) {
        Write "No pivot-family widgets found on '"_pDashboardFullName_"' - nothing converted", !
        Quit
    }

    Set tSC = tDash.%Save()
    If $$$ISERR(tSC) Quit

    Write "Converted "_tConverted_" widget(s) on '"_pDashboardFullName_"' to "_pNewType, !
}
Catch ex {
    Set tSC = ex.AsStatus()
}
Quit tSC

Set tSC = $$$OK
Try {
    Set tDash = ##class(%DeepSee.Dashboard.Utils).%OpenDashboard(pDashboardFullName, .tSC)
    If $$$ISERR(tSC) Quit
    If '$IsObject(tDash) {
        Set tSC = $$$ERROR($$$GeneralError, "Dashboard not found: "_pDashboardFullName)
        Quit
    }

    Set tWidget = ""
    For i=1:1:tDash.widgets.Count() {
        Set w = tDash.widgets.GetAt(i)
        If (w.name = pWidgetName) {
            Set tWidget = w
            Quit
        }
    }
    If '$IsObject(tWidget) {
        Set tSC = $$$ERROR($$$GeneralError, "Widget not found on '"_pDashboardFullName_"': "_pWidgetName)
        Quit
    }

    Set tWidget.type = "pivot"
    Set tSC = tDash.%Save()
    If $$$ISERR(tSC) Quit

    Write "Reverted '"_pWidgetName_"' on '"_pDashboardFullName_"' to stock 'pivot'", !
}
Catch ex {
    Set tSC = ex.AsStatus()
}
Quit tSC

If '$IsObject(pOptions) { Set pOptions = {} }
Set tResult = {}
Set tResult."title" = ..%StrOrNull(pOptions.title)
Set tResult."subtitle" = ..%StrOrNull(pOptions.subtitle)
Set tResult."cube" = ..%StrOrNull(pOptions.cube)
If (pOptions.filters = "") {
    Set tResult.filters = []
} Else {
    Set tResult.filters = pOptions.filters
}
Set tRowCaptions = ..%ParseCaptions(pOptions.%Get("rowCaptions"))

Set tRS = ##class(%DeepSee.ResultSet).%New()
Set tSC = tRS.%PrepareMDX(pMDX)
If $$$ISERR(tSC) Throw ##class(%Exception.StatusException).CreateFromStatus(tSC)

Set tListingName = pOptions.%Get("listing", "")
If (tListingName '= "") {
    Set tSC = tRS.%SetListing(tListingName)
    If $$$ISERR(tSC) Throw ##class(%Exception.StatusException).CreateFromStatus(tSC)
}
Set tRS.%Query.%MaxListingRows = 0

Set tSC = tRS.%ExecuteAsynch(,,1)
If $$$ISERR(tSC) Throw ##class(%Exception.StatusException).CreateFromStatus(tSC)

If tRS.%IsDrillThrough() {
    Set tResult.kind = "listing"
    Do ..%BuildListing(tRS, tResult)
} Else {
    Set tResult.kind = "cellset"
    Set tRowTotals = $Select($IsObject(pOptions):(pOptions.rowTotals=1),1:0)
    Set tColTotals = $Select($IsObject(pOptions):(pOptions.columnTotals=1),1:0)
    Set tRowTotalAgg = $Select($IsObject(pOptions)&&(pOptions.%Get("rowTotalAgg","")'=""):pOptions.rowTotalAgg,1:"sum")
    Set tColTotalAgg = $Select($IsObject(pOptions)&&(pOptions.%Get("columnTotalAgg","")'=""):pOptions.columnTotalAgg,1:"sum")
    Do ..%BuildCellset(tRS, tResult, tRowTotals, tColTotals, tRowTotalAgg, tColTotalAgg)

    Set tRowHeaderNames = []
    For n=1:1:tResult.rowHeaderDepth {
        Do tRowHeaderNames.%Push($Select(n<=tRowCaptions.Count():tRowCaptions.GetAt(n),1:""))
    }
    Set tResult.rowHeaderNames = tRowHeaderNames
}

Quit tResult

Set tList = ##class(%ListOfDataTypes).%New()
If $IsObject($Get(pValue)) {
    For i=0:1:pValue.%Size()-1 { Do tList.Insert(pValue.%Get(i)) }
} ElseIf ($Get(pValue) '= "") {
    For i=1:1:$Length(pValue,$C(10)) { Do tList.Insert($Piece(pValue,$C(10),i)) }
}
Quit tList

Set tSC = pRS.%GetListingResultSet(.tListingRS, .tListingFields)
If $$$ISERR(tSC) Throw ##class(%Exception.StatusException).CreateFromStatus(tSC)

Set tColumnMeta = tListingRS.%GetMetaData().columns
Set tColumns = []
If (tListingFields = "") {
    Set tColCount = tColumnMeta.Count()
    For c=1:1:tColCount {
        Set tInfo = tColumnMeta.GetAt(c)
        Set tNumeric = $Case(tInfo.ODBCType, 2:1, 4:1, 8:1, :0)
        Do tColumns.%Push({"name": (tInfo.colName), "numeric": (tNumeric)})
    }
} Else {
    Set tColCount = $ListLength(tListingFields)
    For c=1:1:tColCount {
        Do tColumns.%Push({"name": ($ListGet(tListingFields,c)), "numeric": 0})
    }
}
Set pResult.columns = tColumns

Set tRows = []
While tListingRS.%Next(.tSC) {
    If $$$ISERR(tSC) Throw ##class(%Exception.StatusException).CreateFromStatus(tSC)
    Set tRow = []
    For c=1:1:tColCount {
        If (tListingFields = "") {
            Set tValue = tListingRS.%GetData(c)
        } Else {
            Set tValue = tListingRS.%Get($ListGet(tListingFields,c))
        }
        Do tRow.%Push(tValue)
    }
    Do tRows.%Push(tRow)
}
Set pResult.rows = tRows

Set tAxisCount = pRS.%GetAxisCount()

// Single-value answer (no axes) - report it as a 1x1 table.
If (tAxisCount = 0) {
    Set tValue = pRS.%GetValue()
    Set pResult.colHeaderDepth = 1
    Set pResult.rowHeaderDepth = 1
    Set pResult.colCount = 1
    Set pResult.rowCount = 1
    Set pResult.columnHeaders = [["All"]]
    Set pResult.rowHeaders = [["Count"]]
    Set tCell = ..%MakeNumericCell(tValue, "")
    Set tRowArr = []
    Do tRowArr.%Push(tCell)
    Set tData = []
    Do tData.%Push(tRowArr)
    Set pResult.cells = tData
    Quit
}

For a=1:1:tAxisCount { Set tAxisSize(a) = pRS.%GetAxisSize(a) }
Set tColCount = +$Get(tAxisSize(1))
Set tHasRows = (tAxisCount >= 2)
Set tRowCount = $Select(tHasRows:+$Get(tAxisSize(2)),1:1)

If (tColCount = 0) || (tRowCount = 0) {
    Set pResult.colHeaderDepth = 0
    Set pResult.rowHeaderDepth = 0
    Set pResult.colCount = 0
    Set pResult.rowCount = 0
    Set pResult.columnHeaders = []
    Set pResult.rowHeaders = []
    Set pResult.cells = []
    Quit
}

// First pass: column headers + per-column format/solve order.
Set tColHeaderDepth = 1
For c=1:1:tColCount {
    Kill tNames
    Set tCount = pRS.%GetOrdinalLabel(.tNames,1,c,.tFormat,.tSolveOrder)
    Set:(tCount>tColHeaderDepth) tColHeaderDepth = tCount
    Set tColFormat(c) = tFormat
    Set tColSolveOrder(c) = tSolveOrder
    For n=1:1:tCount { Set tColLabel(c,n) = $Get(tNames(n)) }
}

// Second pass: row headers + per-row format/solve order.
Set tRowHeaderDepth = 1
If (tHasRows) {
    For r=1:1:tRowCount {
        Kill tLabels
        Set tCount = pRS.%GetOrdinalLabel(.tLabels,2,r,.tFormat,.tSolveOrder)
        Set:(tCount>tRowHeaderDepth) tRowHeaderDepth = tCount
        Set tRowFormat(r) = tFormat
        Set tRowSolveOrder(r) = tSolveOrder
        For n=1:1:tCount { Set tRowLabel(r,n) = $Get(tLabels(n)) }
    }
} Else {
    Set tRowFormat(1) = ""
    Set tRowSolveOrder(1) = 0
    Set tRowLabel(1,1) = "Results"
}

Set tDefaultFormat = pRS.%GetDefaultFormat()
Set tHasOverride = pRS.%HasCellFormatOverride()

// Column headers, outermost (depth tColHeaderDepth) first, innermost (1) last - top-to-bottom.
// Pushed with explicit type "string" - member captions that happen to look numeric
// (e.g. a Year value "2024", or a flag member "0"/"1") would otherwise get
// auto-detected as JSON numbers, producing a mixed string/number array that crashes
// XLSXWriter's header-flattening join for any pivot with a ragged/asymmetric column axis.
Set tColumnHeaders = []
For lvl=tColHeaderDepth:-1:1 {
    Set tRowOfHeaders = []
    For c=1:1:tColCount {
        Do tRowOfHeaders.%Push($Get(tColLabel(c,lvl)),"string")
    }
    Do tColumnHeaders.%Push(tRowOfHeaders)
}
Set pResult.columnHeaders = tColumnHeaders

// Row headers, outermost (depth) first, innermost (1) last - left-to-right per row.
Set tRowHeaders = []
For r=1:1:tRowCount {
    Set tHeaderRow = []
    For lvl=tRowHeaderDepth:-1:1 {
        Do tHeaderRow.%Push($Get(tRowLabel(r,lvl)),"string")
    }
    Do tRowHeaders.%Push(tHeaderRow)
}
Set pResult.rowHeaders = tRowHeaders

Set pResult.colHeaderDepth = tColHeaderDepth
Set pResult.rowHeaderDepth = tRowHeaderDepth
Set pResult.colCount = tColCount
Set pResult.rowCount = tRowCount

// Data cells.
Set tData = []
For r=1:1:tRowCount {
    Set tRowArr = []
    For c=1:1:tColCount {
        Set tValue = $Case(tAxisCount, 1:pRS.%GetOrdinalValue(c), :pRS.%GetOrdinalValue(c,r))

        If (+$Get(tColSolveOrder(c)) >= +$Get(tRowSolveOrder(r))) {
            Set tFormat = $Select($Get(tColFormat(c))'="":tColFormat(c), $Get(tRowFormat(r))'="":tRowFormat(r), 1:tDefaultFormat)
        } Else {
            Set tFormat = $Select($Get(tRowFormat(r))'="":tRowFormat(r), $Get(tColFormat(c))'="":tColFormat(c), 1:tDefaultFormat)
        }
        If ((tAxisCount>1) && tHasOverride) {
            Set tFO = pRS.%GetCellFormatOverride(c,r)
            Set:tFO'="" tFormat = tFO
        }

        Do tRowArr.%Push(..%MakeCell(tValue, tFormat))
    }
    Do tData.%Push(tRowArr)
}
Set pResult.cells = tData

If ('pRowTotals) && ('pColTotals) Quit

// Column totals: one value per column, summed down the rows - rendered as a "Total" row.
// "pct" (% of Total) returns a raw 0-1 fraction, not a value in the column's own
// units, so it needs its own percent format rather than the column's normal one.
If (pColTotals) {
    Set tColTotals = []
    Set tColPct = (pColTotalAgg="pct")
    For c=1:1:tColCount {
        Set tFormat = $Select(tColPct:"0.00%",$Get(tColFormat(c))'="":tColFormat(c),1:tDefaultFormat)
        Do tColTotals.%Push(..%MakeCell(pRS.%GetColumnTotal(c,pColTotalAgg),tFormat))
    }
    Set pResult.columnTotals = tColTotals
    Set pResult.columnTotalAgg = pColTotalAgg
}

// Row totals: one value per row, summed across columns - rendered as a "Total" column.
// Grand total is only meaningful (and only used by the writer) alongside row totals.
If (pRowTotals) {
    Set tRowTotals = []
    Set tGrandTotal = 0
    Set tRowPct = (pRowTotalAgg="pct")
    For r=1:1:tRowCount {
        Set tFormat = $Select(tRowPct:"0.00%",$Get(tRowFormat(r))'="":tRowFormat(r),1:tDefaultFormat)
        Set tSum = pRS.%GetRowTotal(r,pRowTotalAgg)
        Set tGrandTotal = tGrandTotal + tSum
        Do tRowTotals.%Push(..%MakeCell(tSum,tFormat))
    }
    Set pResult.rowTotals = tRowTotals
    Set pResult.rowTotalAgg = pRowTotalAgg
    Set pResult.grandTotal = ..%MakeCell(tGrandTotal,$Select(tRowPct:"0.00%",1:tDefaultFormat))
}

If (pFormat = "%string%") {
    Quit {"t":"s","v":(pValue),"fmt":"@"}
}
ElseIf (pFormat = "%date%") {
    If (pValue = "") {
        Quit {"t":"s","v":""}
    }
    Set tISO = $ZDT(pValue\1,3)
    Quit {"t":"d","v":(tISO),"fmt":"mm/dd/yyyy"}
}
ElseIf (pFormat = "%time%") {
    Quit {"t":"t","v":(+pValue),"fmt":"[h]:mm:ss"}
}
Else {
    Quit ..%MakeNumericCell(pValue, pFormat)
}

If $IsValidNum(pValue) {
    Quit {"t":"n","v":(+pValue),"fmt":(..%TranslateFormat(pFormat))}
}
Quit {"t":"s","v":(pValue),"fmt":"@"}

Set tSC = $$$OK
Try {
    Set tBytes = ..BuildTiny()
    Set tStream = ##class(%Stream.FileBinary).%New()
    Set tSC = tStream.LinkToFile(pFile)
    If $$$ISERR(tSC) Quit
    Do tStream.Write(tBytes)
    Set tSC = tStream.%Save()
}
Catch ex {
    Set tSC = ex.AsStatus()
}
Quit tSC

try {
    // One round-trip for the whole page (availability can't differ per dropdown) rather
    // than one per menu found below.
    var xlsxStatus = zenPage.IsXLSXAvailable();
    var xlsxAvailable = (xlsxStatus.charAt(0) === '1');
    var xlsxReason = xlsxAvailable ? '' : xlsxStatus.substring(2);

    var menus = document.querySelectorAll('.dsptIconDropdownMenu');
    for (var i = 0; i < menus.length; i++) {
        var menu = menus[i];
        if (menu.getAttribute('data-extraExportAdded')) { continue; }

        var links = menu.getElementsByTagName('a');
        var excelLink = null;
        for (var j = 0; j < links.length; j++) {
            var onclickAttr = links[j].getAttribute('onclick') || '';
            if (onclickAttr.indexOf('exportExcel') >= 0) {
                excelLink = links[j];
                break;
            }
        }
        if (!excelLink) { continue; }

        var match = (excelLink.getAttribute('onclick') || '').match(/toggleExportMenu\('([^']+)'\)/);
        var menuId = match ? match[1] : '';

        var xlsxLink = document.createElement('a');
        if (xlsxAvailable) {
            xlsxLink.setAttribute('title', 'Microsoft Excel Workbook (.xlsx)');
            xlsxLink.setAttribute('onclick', "zenPage.toggleExportMenu('" + menuId + "');zenPage.exportXLSX();");
        } else {
            xlsxLink.setAttribute('title', xlsxReason);
            xlsxLink.style.color = '#999999';
            xlsxLink.style.cursor = 'not-allowed';
        }
        xlsxLink.textContent = 'Excel Workbook';
        excelLink.parentNode.insertBefore(xlsxLink, excelLink.nextSibling);

        var jsonLink = document.createElement('a');
        jsonLink.setAttribute('title', 'JSON (.json)');
        jsonLink.setAttribute('onclick', "zenPage.toggleExportMenu('" + menuId + "');zenPage.exportJSON();");
        jsonLink.textContent = 'JSON';
        xlsxLink.parentNode.insertBefore(jsonLink, xlsxLink.nextSibling);

        menu.setAttribute('data-extraExportAdded', '1');
    }
}
catch (e) {
    // Non-fatal: if the stock page's DOM structure ever changes enough that this
    // stops finding the menu, just skip adding the options rather than break the page.
}

var table = this.getPivot();
if (!table || ('' == table.cubeName) || ('' == table.queryKey)) {
    return '';
}

var mdx = table.GetCurrentQueryText("export");
var nonce = '';
if (mdx.toString().length > 1000) {
    // avoid long urls for IE!
    nonce = this.CreateQueryNonce(mdx);
    if (nonce.toString().indexOf('ERROR:') >= 0) {
        alert(nonce);
        return '';
    }
}

var url;
if (nonce) {
    url = pPage + '?NONCE=' + encodeURIComponent(nonce);
}
else {
    url = pPage + '?MDX=' + encodeURIComponent(mdx);
}

var title = table.printTitle;
var subtitle = table.printSubtitle;
if (title == '') {
    title = this.pivotName;
    if (title != '') {
        var s = title.toString().split('.');
        s.length = s.length - 1;
        title = s.join('.');
    }
}
// Strip any BI-folder path prefix ("Test/Crossjoin...") - that's portal
// organization, not part of the report's identity, and shouldn't leak into
// the filename or the Info sheet's title.
if (title.indexOf('/') >= 0) {
    var pathParts = title.split('/');
    title = pathParts[pathParts.length - 1];
}
url += '&TITLE=' + encodeURIComponent(title);
url += '&SUBTITLE=' + encodeURIComponent(subtitle);
url += '&CUBE=' + encodeURIComponent(table.cubeName || '');
if (table.listing != '') {
    url += '&LISTINGNAME=' + encodeURIComponent(table.listing);
}
// table.rowTotals/table.columnTotals are independent pivot options - a pivot can
// have either, both, or neither. These must stay separate params: OR-ing them into
// one combined flag made the export always render BOTH totals whenever ONE was
// enabled, adding an unrequested "Total" column/row that often summed unrelated
// measures together.
//
// The widget's own property names are the OPPOSITE of what they render: checking
// "Row Options -> Summary" sets table.rowTotals=true (and table.rowTotalAgg to the
// aggregation dropdown next to it) but renders an extra Totals ROW (confirmed live -
// Pivot Options dialog, control_21), and "Column Options -> Summary"
// (table.columnTotals/table.columnTotalAgg) renders an extra Totals COLUMN.
// ROWTOTALS/COLUMNTOTALS on our own REST API mean what they say (see MDXExport.cls's
// doc comment: ROWTOTALS = "Total" column, COLUMNTOTALS = "Total" row), so the
// mapping below - flags AND their aggregation functions - is deliberately crossed to
// match what actually renders in the Analyzer, not the widget's own (misleading)
// property names. table.rowTotalAgg/table.columnTotalAgg values ("sum", "count",
// "min", "max", "avg", "pct") pass straight through with no translation - they're
// exactly what MDXExport.cls's rowTotalAgg/columnTotalAgg options (and
// %DeepSee.ResultSet's own %GetRowTotal/%GetColumnTotal) expect.
if (table.rowTotals) {
    url += '&COLUMNTOTALS=1';
    if (table.rowTotalAgg) {
        url += '&COLUMNTOTALAGG=' + encodeURIComponent(table.rowTotalAgg);
    }
}
if (table.columnTotals) {
    url += '&ROWTOTALS=1';
    if (table.columnTotalAgg) {
        url += '&ROWTOTALAGG=' + encodeURIComponent(table.columnTotalAgg);
    }
}
// Row axis dimension/level captions (e.g. "YearSold","Product Category") - the
// ResultSet API has no way to derive these; the pivot table widget already has
// them client-side. Same source stock exportExcel() uses for its ROWCAPTIONS param.
url += '&ROWCAPTIONS=' + encodeURIComponent(table.getRowCaptions().join('\n'));

// The pivot's active filter selections (e.g. Product Category = Cereal+Dairy+...)
// for the Info sheet's recap block - same table.getFilterInfo() call stock
// exportExcel() uses for its FILTERNAMES/FILTERVALUES params.
var filterNames = [];
var filterValues = [];
table.getFilterInfo(filterNames, filterValues);
if (filterNames.length > 0) {
    url += '&FILTERNAMES=' + encodeURIComponent(filterNames.join('\n'));
    url += '&FILTERVALUES=' + encodeURIComponent(filterValues.join('\n'));
}

var fileBase;
if (title) {
    fileBase = title;
}
else {
    // Ad-hoc pivot built in the Analyzer and never saved - no name to hang a
    // filename on. Fall back to the cube plus a short timestamp instead of a
    // bare "export.xlsx" that every such download would collide on.
    var now = new Date();
    var pad = function(n) { return (n < 10 ? '0' : '') + n; };
    var ts = now.getFullYear() + pad(now.getMonth() + 1) + pad(now.getDate()) + '-' + pad(now.getHours()) + pad(now.getMinutes());
    fileBase = (table.cubeName ? table.cubeName : 'export') + '_' + ts;
}
url += '&FILENAME=' + encodeURIComponent(fileBase + '.' + pExtension);

return zenLink(url);

Do ##super(.pMenu)
Set tNext = $Order(pMenu(""),-1) + 1
// Whole-dashboard export needs Python too (BuildMultiSheetXLSX, same as the per-widget
// button) - gated here the same way as BIExport.UI.Widget.pivot's dropdown option, since
// this menu is also built entirely server-side. Confirmed live (dumping %DrawSmallMenu's
// compiled source) that this row shape - $ListBuild(caption,title,script) - has no visual
// "disabled" concept: every row renders with the identical "portalTitleLink" CSS class
// regardless of what's in it, and an empty script just makes the link's onclick a no-op
// ("return false;", no JS error) - so this can't be grayed out the way the pivot widget's
// dropdown option field (raw HTML) can. Still shown (not omitted) with a distinct caption
// and the reason as its hover tooltip, since a click-time landing on a friendly error is
// strictly worse discoverability than a link that's visibly there but explains itself on
// hover and does nothing when clicked.
//
// %DrawSmallMenu HTML-escapes the caption (position 1) itself but writes the title/tooltip
// (position 2) verbatim - confirmed the same way - so tXlsxReason is escaped here before
// going into that slot.
If ##class(BIExport.XLSXWriter).IsAvailable(.tXlsxReason) {
    Set pMenu(tNext) = $ListBuild("Export Dashboard", "Export every pivot widget on this dashboard into one multi-sheet Excel workbook", "zenPage.exportDashboardXLSX();")
} Else {
    Set pMenu(tNext) = $ListBuild("Export Dashboard (unavailable)", $ZCVT(tXlsxReason,"O","HTML"), "")
}

if (!this.dashboardName) {
    alert('No dashboard is currently loaded.');
    return;
}
var url = 'BIExport.UI.DashboardXLSXPage.cls?DASHBOARD=' + encodeURIComponent(this.dashboardName);
window.open(zenLink(url), 'dashboardxlsx', '');

If (pDashboardFullName = "") Quit "dashboard-export.xlsx"
Set tName = pDashboardFullName
If (tName [ "/") { Set tName = $Piece(tName,"/",$Length(tName,"/")) }
If ($ZConvert($Piece(tName,".",$Length(tName,".")),"L") = "dashboard") {
    Set tName = $Piece(tName,".",1,$Length(tName,".")-1)
}
Quit tName _ ".xlsx"

Set tSC = $$$OK
Try {
    // OnPreHTTP() already made the actual response-header decision (too late here -
    // see that method's doc comment); this just re-checks to decide whether to write
    // the error body or the real export.
    If '##class(BIExport.XLSXWriter).IsAvailable(.tReason) {
        Do ..%WriteUnavailablePage(tReason)
        Quit
    }

    Set tDashboard = $Get(%request.Data("DASHBOARD",1))
    If (tDashboard = "") {
        Set %response.Status = "400 Bad Request"
        Write "Missing DASHBOARD parameter"
        Quit
    }

    Set tData = ##class(BIExport.DashboardExport).BuildDashboardExportData(tDashboard, .tExportSC)
    If $$$ISERR(tExportSC) Throw ##class(%Exception.StatusException).CreateFromStatus(tExportSC)

    Set tBytes = ##class(BIExport.XLSXWriter).BuildMultiSheetXLSX(tData.%ToJSON())

    Set tStream = ##class(%Stream.TmpBinary).%New()
    Do tStream.Write(tBytes)
    Do tStream.Rewind()
    Do tStream.OutputToDevice()
}
Catch ex {
    Set %response.Status = "500 Internal Server Error"
    Write ex.DisplayString()
}
Quit $$$OK

    Set tXLSXAvailable = ##class(BIExport.XLSXWriter).IsAvailable(.tReason)

    &html<<!DOCTYPE html>
<html>
<head>
<title>bi-export-plus - Live Demo</title>
<meta charset="utf-8">
<style>
  body { font-family: Calibri, "Segoe UI", Arial, sans-serif; margin: 0; background: #F4F6FA; color: #1B2A4A; }
  header { background: #1B2A4A; color: #fff; padding: 18px 32px; }
  header h1 { margin: 0; font-size: 22px; }
  header p { margin: 4px 0 0; color: #AAB8D6; font-size: 13px; }
  main { max-width: 780px; margin: 28px auto; padding: 0 20px; }
  .card { background: #fff; border-radius: 8px; padding: 24px 28px; box-shadow: 0 1px 4px rgba(0,0,0,0.08); margin-bottom: 20px; }
  .card h2 { font-size: 15px; margin: 0 0 14px; color: #1B2A4A; }
  label { display: block; font-size: 13px; font-weight: bold; margin: 12px 0 4px; }
  select, textarea, input[type=text] { width: 100%; box-sizing: border-box; font-family: Consolas, monospace; font-size: 13px; padding: 8px; border: 1px solid #D9D9D9; border-radius: 4px; }
  textarea { height: 90px; resize: vertical; }
  .totals-row { display: flex; align-items: center; gap: 10px; margin: 10px 0; }
  .totals-row input[type=checkbox] { width: 16px; height: 16px; }
  .totals-row select { width: auto; flex: 1; }
  .totals-row .lbl { font-size: 13px; font-weight: normal; flex: 2; }
  .buttons { margin-top: 18px; display: flex; gap: 12px; }
  button { flex: 1; padding: 12px; font-size: 14px; font-weight: bold; border: none; border-radius: 5px; cursor: pointer; color: #fff; }
  button:disabled { background: #B0B7C3; cursor: not-allowed; }
  #btnXlsx { background: #4472C4; }
  #btnXlsx:hover { background: #35599e; }
  #btnJson { background: #595959; }
  #btnJson:hover { background: #404040; }
  .hint { font-size: 12px; color: #808080; margin-top: 6px; }
  .banner { background: #FDEDED; border: 1px solid #F5C2C2; border-radius: 6px; padding: 12px 16px; margin-bottom: 20px; font-size: 13px; }
  .banner b { display: block; margin-bottom: 4px; }
</style>
</head>
<body>
<header>
  <h1>bi-export-plus</h1>
  <p>Live demo &mdash; real .xlsx / .json exports straight from MDX, no pivot required</p>
</header>
<main>>

    If ('tXLSXAvailable) {
        &html<<div class="banner">
    <b>Excel Workbook export is disabled - see below. JSON export still works.</b>
    #($ZCVT(tReason,"O","HTML"))#
  </div>>
    }

    &html<<div class="card">
    <h2>1. Pick a query</h2>
    <select id="preset" onchange="applyPreset()">
      <option value="simple">Simple &mdash; Revenue &amp; Units by Region</option>
      <option value="totals">With totals &mdash; Sales by Year</option>
      <option value="nested">Nested column headers &mdash; Sales by Year and Channel</option>
      <option value="custom">Custom MDX&hellip;</option>
    </select>

    <label for="mdx">MDX query</label>
    <textarea id="mdx" oninput="syncFiltersFromMdx()"></textarea>

    <label for="title">Report title</label>
    <input type="text" id="title">

    <label for="filters">Filters (one per line, <code>Name = Value</code>)</label>
    <textarea id="filters" placeholder="Region = West"></textarea>
    <p class="hint">Auto-parsed from the query's <code>%FILTER</code> clause when you paste MDX (e.g. straight from the Analyzer) - shows raw member keys, not resolved friendly captions, since that's all a bare MDX string carries. Still shown as an editable recap block on the exported Info sheet, so tweak it by hand if you want nicer labels/values.</p>
  </div>

  <div class="card">
    <h2>2. Totals</h2>
    <div class="totals-row">
      <input type="checkbox" id="rowTotals">
      <span class="lbl">Total <b>column</b> (one value per row, summed across columns)</span>
      <select id="rowTotalAgg">
        <option value="sum">Sum</option>
        <option value="count">Count</option>
        <option value="min">Min</option>
        <option value="max">Max</option>
        <option value="avg">Average</option>
        <option value="pct">% of Total</option>
      </select>
    </div>
    <div class="totals-row">
      <input type="checkbox" id="columnTotals">
      <span class="lbl">Total <b>row</b> (one value per column, summed down rows)</span>
      <select id="columnTotalAgg">
        <option value="sum">Sum</option>
        <option value="count">Count</option>
        <option value="min">Min</option>
        <option value="max">Max</option>
        <option value="avg">Average</option>
        <option value="pct">% of Total</option>
      </select>
    </div>
    <p class="hint">Independent switches - turn on either, both, or neither.</p>
  </div>

  <div class="buttons">>

    If (tXLSXAvailable) {
        Write "<button id=""btnXlsx"" onclick=""doExport('xlsx')"">Download Excel Workbook</button>",!
    } Else {
        Write "<button id=""btnXlsx"" disabled title=""" _ $ZCVT(tReason,"O","HTML") _ """>Download Excel Workbook</button>",!
    }

    &html<<button id="btnJson" onclick="doExport('json')">Download JSON</button>
  </div>
</main>

<script>
var PRESETS = {
  simple: {
    mdx: "SELECT {[Measures].[Amount Sold],[Measures].[Units Sold]} ON COLUMNS, NON EMPTY [Outlet].[H1].[Region].Members ON ROWS FROM [HOLEFOODS]",
    title: "HoleFoods by Region",
    cube: "HOLEFOODS",
    rowCaptions: "Region"
  },
  totals: {
    mdx: "SELECT {[Measures].[%COUNT],[Measures].[Amount Sold],[Measures].[Units Sold]} ON COLUMNS, NON EMPTY [DateOfSale].[Actual].[YearSold].Members ON ROWS FROM [HOLEFOODS]",
    title: "Sales by Year",
    cube: "HOLEFOODS",
    rowCaptions: "YearSold"
  },
  nested: {
    mdx: "SELECT Crossjoin([Channel].Members,{[Measures].[%COUNT],[Measures].[Amount Sold],[Measures].[Units Sold]}) ON COLUMNS, NON EMPTY [DateOfSale].[Actual].[YearSold].Members ON ROWS FROM [HOLEFOODS]",
    title: "Sales by Year and Channel",
    cube: "HOLEFOODS",
    rowCaptions: "YearSold"
  },
  custom: { mdx: "", title: "", cube: "HOLEFOODS", rowCaptions: "" }
};

// Best-effort: pulls member keys out of the query's %FILTER clause by regex, grouped
// by their innermost level name (the bracket segment right before the final ".&[key]"
// or ".[MemberName]"). Raw MDX carries no friendly dimension/level captions - the
// %DeepSee.ResultSet API can't derive those either (see CLAUDE.md) - so this shows
// keys as they appear in the query, not resolved display names.
function extractFiltersFromMDX(mdx) {
  var idx = mdx.search(/%FILTER\b/i);
  if (idx === -1) { return []; }
  var clause = mdx.slice(idx);
  var re = /((?:\[[^\]]+\]\.)+)&?\[([^\]]+)\]/g;
  var order = [];
  var groups = {};
  var m;
  while ((m = re.exec(clause)) !== null) {
    var segments = m[1].match(/\[([^\]]+)\]/g).map(function (s) { return s.slice(1, -1); });
    var level = segments[segments.length - 1];
    var key = m[2];
    if (!groups[level]) { groups[level] = []; order.push(level); }
    groups[level].push(key);
  }
  return order.map(function (level) { return level + ' = ' + groups[level].join(', '); });
}

function syncFiltersFromMdx() {
  document.getElementById('filters').value = extractFiltersFromMDX(document.getElementById('mdx').value).join('\n');
}

function applyPreset() {
  var p = PRESETS[document.getElementById('preset').value];
  document.getElementById('mdx').value = p.mdx;
  document.getElementById('title').value = p.title;
  syncFiltersFromMdx();
}

function doExport(ext) {
  var mdx = document.getElementById('mdx').value;
  if (!mdx) { alert('Enter an MDX query first.'); return; }
  var preset = PRESETS[document.getElementById('preset').value] || PRESETS.custom;
  var title = document.getElementById('title').value;

  var page = (ext === 'xlsx') ? 'BIExport.UI.XLSXPage.cls' : 'BIExport.UI.JSONPage.cls';
  var url = page + '?MDX=' + encodeURIComponent(mdx);
  url += '&TITLE=' + encodeURIComponent(title);
  url += '&CUBE=' + encodeURIComponent(preset.cube || '');
  if (preset.rowCaptions) {
    url += '&ROWCAPTIONS=' + encodeURIComponent(preset.rowCaptions);
  }

  var filterNames = [];
  var filterValues = [];
  document.getElementById('filters').value.split('\n').forEach(function (line) {
    var eq = line.indexOf('=');
    if (eq === -1) { return; }
    var name = line.slice(0, eq).trim();
    var value = line.slice(eq + 1).trim();
    if (!name) { return; }
    filterNames.push(name);
    filterValues.push(value);
  });
  if (filterNames.length > 0) {
    url += '&FILTERNAMES=' + encodeURIComponent(filterNames.join('\n'));
    url += '&FILTERVALUES=' + encodeURIComponent(filterValues.join('\n'));
  }

  if (document.getElementById('rowTotals').checked) {
    url += '&ROWTOTALS=1&ROWTOTALAGG=' + document.getElementById('rowTotalAgg').value;
  }
  if (document.getElementById('columnTotals').checked) {
    url += '&COLUMNTOTALS=1&COLUMNTOTALAGG=' + document.getElementById('columnTotalAgg').value;
  }
  url += '&FILENAME=' + encodeURIComponent((title || 'export') + '.' + ext);
  window.open(url, '_blank');
}

applyPreset();
</script>
</body>
</html>>
    Quit $$$OK

Set tSC = $$$OK
Try {
    Set tNonce = $Get(%request.Data("NONCE",1))
    If (tNonce '= "") {
        Set tMDX = $Get($$$DeepSeeQueryNonceGLVN(tNonce))
        Kill $$$DeepSeeQueryNonceGLVN(tNonce)
    } Else {
        Set tMDX = $Get(%request.Data("MDX",1))
    }
    If (tMDX = "") {
        Set %response.Status = "400 Bad Request"
        Quit
    }

    Set tOptions = {}
    Set tOptions.title = $Get(%request.Data("TITLE",1))
    Set tOptions.subtitle = $Get(%request.Data("SUBTITLE",1))
    Set tOptions.cube = $Get(%request.Data("CUBE",1))
    Set tOptions.listing = $Get(%request.Data("LISTINGNAME",1))
    Set tOptions.rowTotals = ($Get(%request.Data("ROWTOTALS",1)) = "1")
    Set tOptions.columnTotals = ($Get(%request.Data("COLUMNTOTALS",1)) = "1")
    Set tOptions.rowTotalAgg = $Get(%request.Data("ROWTOTALAGG",1))
    Set tOptions.columnTotalAgg = $Get(%request.Data("COLUMNTOTALAGG",1))
    Set tOptions.rowCaptions = $Get(%request.Data("ROWCAPTIONS",1))
    Set tOptions.filters = ##class(BIExport.MDXExport).%ParseFilterPairs($Get(%request.Data("FILTERNAMES",1)), $Get(%request.Data("FILTERVALUES",1)))

    Set tData = ##class(BIExport.MDXExport).BuildExportData(tMDX, tOptions)

    Do tData.%ToJSON()
}
Catch ex {
    Set %response.Status = "500 Internal Server Error"
    Write ex.DisplayString()
}
Quit $$$OK

Set tPrevCount = pGroup.children.Count()
Set tSC = ##super(pGroup)
If $$$ISERR(tSC) Quit tSC

Try {
    Do ..%GetWidgetPropertyInfo(..subtype, .tList)
    Set n = $Order(tList(""))
    While (n '= "") {
        Set tName = $ListGet(tList(n), 1)
        Set tPValue(tName) = ..%definition.properties.GetAt(tName)
        Set:tPValue(tName)="" tPValue(tName) = $ListGet(tList(n), 2)
        Set n = $Order(tList(n))
    }

    Set tExcelOn = +$Get(tPValue("excel"))
    Set tCsvOn = +$Get(tPValue("csv"))

    // Only the single-icon case needs converting - genuine csv=1 widgets already
    // got a real dropdown from the stock method above, and the client-side
    // onloadHandler()/addExtraExportOptions() DOM-patches those instead.
    If (tExcelOn || tCsvOn) && ('tCsvOn) {
        // Positional lookup - see method doc comment for why. Mirrors the exact
        // order stock %OnCreateControls adds siblings in: chart toggle, then
        // dimension list, then PDF, then (here) export.
        Set tExportPos = tPrevCount
        Set:(..chartToggle="table")||(..chartToggle="chart") tExportPos = tExportPos + 1
        Set:..hasDimTree tExportPos = tExportPos + 1
        Set:(+$Get(tPValue("print"))) tExportPos = tExportPos + 1
        Set tExportPos = tExportPos + 1

        Set tImgChild = ""
        If (tExportPos > tPrevCount) && (tExportPos <= pGroup.children.Count()) {
            Set tImgChild = pGroup.children.GetAt(tExportPos)
        }

        If $IsObject(tImgChild) {
            Set tOptions = []

            Set tExcelOpt = {"name":"Excel"}
            Set tExcelOpt.click = "zenPage.getComponent("_..index_").exportExcel();"
            Set tExcelOpt.hover = $$$Text("Microsoft Excel (.xls)","%DeepSee")
            Do tOptions.%Push(tExcelOpt)

            // Grayed out (via a styled span in "name" - %CreateExportDropdown writes this
            // field verbatim as the <a>'s innerHTML, confirmed live by dumping its compiled
            // source, so this is the only per-option visual hook it actually offers - there
            // is no separate "disabled" flag on an individual option) and given no click
            // handler at all when BIExport.XLSXWriter.IsAvailable() reports IRIS Embedded
            // Python/openpyxl aren't available, with the reason as the hover tooltip -
            // guaranteed, not best-effort, since this whole option list is already built
            // server-side. %CreateExportDropdown writes "hover" verbatim into a title=""
            // attribute too (same dump), so it's HTML-escaped here - IsAvailable()'s own
            // reason text quotes CPF parameter values in double quotes, which would
            // otherwise prematurely close that attribute.
            Set tXlsxOpt = {"name":"Excel Workbook"}
            If ##class(BIExport.XLSXWriter).IsAvailable(.tXlsxReason) {
                Set tXlsxOpt.click = "zenPage.getComponent("_..index_").exportXLSX();"
                Set tXlsxOpt.hover = "Microsoft Excel Workbook (.xlsx)"
            } Else {
                Set tXlsxOpt.name = "<span style=""color:#999999;"">Excel Workbook</span>"
                Set tXlsxOpt.hover = $ZCVT(tXlsxReason,"O","HTML")
            }
            Do tOptions.%Push(tXlsxOpt)

            Set tJsonOpt = {"name":"JSON"}
            Set tJsonOpt.click = "zenPage.getComponent("_..index_").exportJSON();"
            Set tJsonOpt.hover = "JSON (.json)"
            Do tOptions.%Push(tJsonOpt)

            Set tHelp = $$$Text("Export current results","%DeepSee")
            Set tHtml = ##class(%ZEN.Component.html).%New()
            Set tHtml.content = ..%CreateExportDropdown(..index, 1, "deepsee/ds2_action_44.png", tHelp, tOptions)

            Do pGroup.%AddChildBefore(tHtml, tImgChild)
            Do pGroup.%RemoveChild(tImgChild)
        }
    }
}
Catch ex {
    // Non-fatal - see method doc comment.
}

Quit tSC

try {
    var container = this.getEnclosingDiv();
    if (!container) { return; }

    // One round-trip per widget instance (not once per menu found below - there's only
    // ever one export dropdown per widget anyway).
    var xlsxStatus = this.IsXLSXAvailable();
    var xlsxAvailable = (xlsxStatus.charAt(0) === '1');
    var xlsxReason = xlsxAvailable ? '' : xlsxStatus.substring(2);

    var menus = container.querySelectorAll('.dsptIconDropdownMenu');
    for (var i = 0; i < menus.length; i++) {
        var menu = menus[i];
        if (menu.getAttribute('data-extraExportAdded')) { continue; }

        var links = menu.getElementsByTagName('a');
        var excelLink = null;
        var alreadyHasXLSX = false;
        for (var j = 0; j < links.length; j++) {
            var onclickAttr = links[j].getAttribute('onclick') || '';
            if (!excelLink && onclickAttr.indexOf('exportExcel') >= 0) {
                excelLink = links[j];
            }
            if (onclickAttr.indexOf('exportXLSX') >= 0) {
                alreadyHasXLSX = true;
            }
        }

        // Server-rendered by %OnCreateControls above (single-icon-widget case) -
        // already has our options, just mark it so it's skipped on future passes.
        if (alreadyHasXLSX) {
            menu.setAttribute('data-extraExportAdded', '1');
            continue;
        }
        if (!excelLink) { continue; }

        var match = (excelLink.getAttribute('onclick') || '').match(/toggleExportMenu\('([^']+)'\)/);
        var menuId = match ? match[1] : '';
        var prefix = 'zenPage.getComponent(' + this.index + ').toggleExportMenu(\'' + menuId + '\');zenPage.getComponent(' + this.index + ').';

        var xlsxLink = document.createElement('a');
        if (xlsxAvailable) {
            xlsxLink.setAttribute('title', 'Microsoft Excel Workbook (.xlsx)');
            xlsxLink.setAttribute('onclick', prefix + 'exportXLSX();');
        } else {
            xlsxLink.setAttribute('title', xlsxReason);
            xlsxLink.style.color = '#999999';
            xlsxLink.style.cursor = 'not-allowed';
        }
        xlsxLink.textContent = 'Excel Workbook';
        excelLink.parentNode.insertBefore(xlsxLink, excelLink.nextSibling);

        var jsonLink = document.createElement('a');
        jsonLink.setAttribute('title', 'JSON (.json)');
        jsonLink.setAttribute('onclick', prefix + 'exportJSON();');
        jsonLink.textContent = 'JSON';
        xlsxLink.parentNode.insertBefore(jsonLink, xlsxLink.nextSibling);

        menu.setAttribute('data-extraExportAdded', '1');
    }
}
catch (e) {
    // Non-fatal: if the stock widget's DOM structure ever changes enough that this
    // stops finding the menu, just skip adding the options rather than break the widget.
}

var table = this.getPivot();
if (!table || ('' == table.cubeName) || ('' == table.queryKey)) {
    return '';
}

var mdx = table.GetCurrentQueryText("export");
var nonce = '';
if (mdx.toString().length > 1000) {
    // avoid long urls for IE!
    nonce = zenPage.CreateQueryNonce(mdx);
    if (nonce.toString().indexOf('ERROR:') >= 0) {
        alert(nonce);
        return '';
    }
}

var url;
if (nonce) {
    url = pPage + '?NONCE=' + encodeURIComponent(nonce);
}
else {
    url = pPage + '?MDX=' + encodeURIComponent(mdx);
}

var widgetDef = this.getDefinition();
var title = (widgetDef && widgetDef.title) ? widgetDef.title : table.printTitle;
var subtitle = table.printSubtitle;
// Strip any BI-folder path prefix ("Test/Crossjoin...") - same reasoning as
// BIExport.UI.Analyzer.buildExportURL(): that's portal organization, not part of
// the report's identity, and shouldn't leak into the filename or Info sheet title.
if (title && title.indexOf('/') >= 0) {
    var pathParts = title.split('/');
    title = pathParts[pathParts.length - 1];
}
url += '&TITLE=' + encodeURIComponent(title || '');
url += '&SUBTITLE=' + encodeURIComponent(subtitle || '');
url += '&CUBE=' + encodeURIComponent(table.cubeName || '');
if (table.listing != '') {
    url += '&LISTINGNAME=' + encodeURIComponent(table.listing);
}
// Crossed ROWTOTALS/COLUMNTOTALS(+AGG) mapping - see CLAUDE.md gotcha #8 and
// BIExport.UI.Analyzer.buildExportURL()'s own comment for the full explanation of
// why table.rowTotals/table.columnTotals are named the opposite of what they render.
if (table.rowTotals) {
    url += '&COLUMNTOTALS=1';
    if (table.rowTotalAgg) {
        url += '&COLUMNTOTALAGG=' + encodeURIComponent(table.rowTotalAgg);
    }
}
if (table.columnTotals) {
    url += '&ROWTOTALS=1';
    if (table.columnTotalAgg) {
        url += '&ROWTOTALAGG=' + encodeURIComponent(table.columnTotalAgg);
    }
}
url += '&ROWCAPTIONS=' + encodeURIComponent(table.getRowCaptions().join('\n'));

var filterNames = [];
var filterValues = [];
table.getFilterInfo(filterNames, filterValues);
if (filterNames.length > 0) {
    url += '&FILTERNAMES=' + encodeURIComponent(filterNames.join('\n'));
    url += '&FILTERVALUES=' + encodeURIComponent(filterValues.join('\n'));
}

var fileBase;
if (title) {
    fileBase = title;
}
else {
    // No title anywhere (ad-hoc widget pivot, no widget title set) - fall back to
    // the cube plus a short timestamp instead of a bare "export.xlsx" that every
    // such download would collide on. Same fallback as the Analyzer version.
    var now = new Date();
    var pad = function(n) { return (n < 10 ? '0' : '') + n; };
    var ts = now.getFullYear() + pad(now.getMonth() + 1) + pad(now.getDate()) + '-' + pad(now.getHours()) + pad(now.getMinutes());
    fileBase = (table.cubeName ? table.cubeName : 'export') + '_' + ts;
}
url += '&FILENAME=' + encodeURIComponent(fileBase + '.' + pExtension);

return zenLink(url);

Set tSC = $$$OK
Try {
    // OnPreHTTP() already made the actual response-header decision (too late to do so
    // here - see that method's doc comment); this just re-checks (cheap, no caching -
    // see BIExport.XLSXWriter.IsAvailable()'s own doc comment) to decide whether to
    // write the error body or the real export.
    If '##class(BIExport.XLSXWriter).IsAvailable(.tReason) {
        Do ..%WriteUnavailablePage(tReason)
        Quit
    }

    Set tNonce = $Get(%request.Data("NONCE",1))
    If (tNonce '= "") {
        Set tMDX = $Get($$$DeepSeeQueryNonceGLVN(tNonce))
        Kill $$$DeepSeeQueryNonceGLVN(tNonce)
    } Else {
        Set tMDX = $Get(%request.Data("MDX",1))
    }
    If (tMDX = "") {
        Set %response.Status = "400 Bad Request"
        Quit
    }

    Set tOptions = {}
    Set tOptions.title = $Get(%request.Data("TITLE",1))
    Set tOptions.subtitle = $Get(%request.Data("SUBTITLE",1))
    Set tOptions.cube = $Get(%request.Data("CUBE",1))
    Set tOptions.listing = $Get(%request.Data("LISTINGNAME",1))
    Set tOptions.rowTotals = ($Get(%request.Data("ROWTOTALS",1)) = "1")
    Set tOptions.columnTotals = ($Get(%request.Data("COLUMNTOTALS",1)) = "1")
    Set tOptions.rowTotalAgg = $Get(%request.Data("ROWTOTALAGG",1))
    Set tOptions.columnTotalAgg = $Get(%request.Data("COLUMNTOTALAGG",1))
    Set tOptions.rowCaptions = $Get(%request.Data("ROWCAPTIONS",1))
    Set tOptions.filters = ##class(BIExport.MDXExport).%ParseFilterPairs($Get(%request.Data("FILTERNAMES",1)), $Get(%request.Data("FILTERVALUES",1)))

    Set tData = ##class(BIExport.MDXExport).BuildExportData(tMDX, tOptions)
    Set tBytes = ##class(BIExport.XLSXWriter).BuildXLSX(tData.%ToJSON())

    Set tStream = ##class(%Stream.TmpBinary).%New()
    Do tStream.Write(tBytes)
    Do tStream.Rewind()
    Do tStream.OutputToDevice()
}
Catch ex {
    Set %response.Status = "500 Internal Server Error"
    Write ex.DisplayString()
}
Quit $$$OK

Set pReason = ""
Set tAvailable = 1
Try {
    Do ##class(%SYS.Python).Import("sys")
} Catch ex {
    Set pReason = "IRIS Embedded Python isn't configured on this instance ("_ex.DisplayString()_"). "
        _ "Set the CPF parameters PythonRuntimeLibrary (path to a supported Python's shared "
        _ "library, e.g. python313.dll) and PythonRuntimeLibraryVersion (major.minor only, "
        _ "e.g. ""3.13"") via Config.config, then restart the instance - see "
        _ "docs/iris-environment.md's ""Embedded Python - required a fix"" section."
    Set tAvailable = 0
}
If (tAvailable) {
    Try {
        Do ##class(%SYS.Python).Import("openpyxl")
    } Catch ex {
        Set pReason = "IRIS Embedded Python is configured, but the openpyxl package isn't "
            _ "importable from it ("_ex.DisplayString()_"). Run pip install openpyxl against "
            _ "whichever Python installation the PythonRuntimeLibrary CPF parameter points at."
        Set tAvailable = 0
    }
}
Quit tAvailable
